"""Exchange holiday calendars, generated by rule, for the holiday_drift family (N1, 2026-11-11).

    exchange_holidays.write()            # write data/calendars/holidays_*.json
    exchange_holidays.write(check=True)  # the venues whose file differs from the rule

A library, not a command: `research.tier1_idea_proposer` calls `write()` on every full sweep,
before holiday_drift reads the files, so the calendars have the proposer's hourly clock.

WHY BY RULE. Every closure below is a published, rule-stated date (a fixed day, the n-th weekday
of a month, Easter, an equinox) plus a short list of announced one-off closures. Rules need no
fetch, no key and no scrape, and they extend to future years the moment a year is added. What a
rule cannot know -- an unannounced closure -- is the one thing this file can get wrong, so the
one-offs are listed by name in SPECIALS and every file says which rules and specials made it.

    nyse   New York Stock Exchange (US500, US30, NAS100, US2000)
    lse    London Stock Exchange (UK100)
    xetra  Deutsche Boerse Xetra (GER40, EUSTX50)
    jpx    Japan Exchange Group / TSE (JPN225)

The files are read by `mt5desk.family_tier1_ideas.holidays`; a file that cannot be read is no
holidays at all, so the family makes no trades -- never "every day".
"""
from __future__ import annotations

import json
from datetime import date, timedelta
from pathlib import Path

DESK = Path(__file__).resolve().parents[1]
OUT = DESK / "data" / "calendars"
YEARS = range(2005, 2036)


def easter(y: int) -> date:
    """Gregorian Easter Sunday (the anonymous Gregorian algorithm)."""
    a, b, c = y % 19, y // 100, y % 100
    d, e = b // 4, b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = c // 4, c % 4
    m = (32 + 2 * e + 2 * i - h - k) % 7
    n = (a + 11 * h + 22 * m) // 451
    month = (h + m - 7 * n + 114) // 31
    return date(y, month, (h + m - 7 * n + 114) % 31 + 1)


def nth_weekday(y: int, month: int, weekday: int, n: int) -> date:
    """The n-th `weekday` (Mon=0) of the month; n=-1 is the last."""
    if n > 0:
        d = date(y, month, 1)
        d += timedelta(days=(weekday - d.weekday()) % 7)
        return d + timedelta(weeks=n - 1)
    d = date(y + (month == 12), month % 12 + 1, 1) - timedelta(days=1)
    return d - timedelta(days=(d.weekday() - weekday) % 7)


def us_observed(d: date) -> date:
    """NYSE rule: Saturday -> Friday, Sunday -> Monday."""
    return d - timedelta(days=1) if d.weekday() == 5 else (
        d + timedelta(days=1) if d.weekday() == 6 else d)


SPECIALS: dict[str, dict[str, str]] = {
    "nyse": {"2007-01-02": "National day of mourning, President Ford",
             "2012-10-29": "Hurricane Sandy", "2012-10-30": "Hurricane Sandy",
             "2018-12-05": "National day of mourning, President G.H.W. Bush",
             "2025-01-09": "National day of mourning, President Carter"},
    "lse": {"2011-04-29": "Royal wedding", "2012-06-05": "Diamond Jubilee",
            "2022-06-03": "Platinum Jubilee", "2022-09-19": "State funeral of Queen Elizabeth II",
            "2023-05-08": "Coronation of King Charles III"},
    "xetra": {},
    "jpx": {"2019-04-30": "Imperial transition", "2019-05-01": "Enthronement day",
            "2019-05-02": "Imperial transition", "2019-10-22": "Enthronement ceremony"},
}


def nyse(y: int) -> set[date]:
    out = {nth_weekday(y, 1, 0, 3), nth_weekday(y, 2, 0, 3), easter(y) - timedelta(days=2),
           nth_weekday(y, 5, 0, -1), us_observed(date(y, 7, 4)), nth_weekday(y, 9, 0, 1),
           nth_weekday(y, 11, 3, 4), us_observed(date(y, 12, 25))}
    ny = date(y, 1, 1)
    if ny.weekday() != 5:                    # a Saturday New Year is not moved to Friday
        out.add(us_observed(ny))
    if y >= 2022:
        out.add(us_observed(date(y, 6, 19)))
    return out


def lse(y: int) -> set[date]:
    ny = date(y, 1, 1)
    out = {ny + timedelta(days={5: 2, 6: 1}.get(ny.weekday(), 0)),
           easter(y) - timedelta(days=2), easter(y) + timedelta(days=1),
           nth_weekday(y, 8, 0, -1)}
    out.add(date(2020, 5, 8) if y == 2020 else (
        date(1995, 5, 8) if y == 1995 else nth_weekday(y, 5, 0, 1)))
    out.add({2012: date(2012, 6, 4), 2022: date(2022, 6, 2)}.get(y, nth_weekday(y, 5, 0, -1)))
    xmas, boxing = date(y, 12, 25), date(y, 12, 26)
    if xmas.weekday() == 5:                  # Sat/Sun pair -> Mon/Tue
        out |= {date(y, 12, 27), date(y, 12, 28)}
    elif xmas.weekday() == 6:                # Sun/Mon -> Tue for Christmas, Mon Boxing Day
        out |= {date(y, 12, 26), date(y, 12, 27)}
    elif boxing.weekday() == 5:              # Fri/Sat -> Boxing Day on Mon
        out |= {xmas, date(y, 12, 28)}
    else:
        out |= {xmas, boxing}
    return out


def xetra(y: int) -> set[date]:
    return {date(y, 1, 1), easter(y) - timedelta(days=2), easter(y) + timedelta(days=1),
            date(y, 5, 1), date(y, 12, 24), date(y, 12, 25), date(y, 12, 26), date(y, 12, 31)}


def _equinox(y: int, base: float) -> int:
    """Day of the March (base 20.8431) or September (23.2488) equinox in Japan, 1980-2099."""
    return int(base + 0.242194 * (y - 1980) - (y - 1980) // 4)


def jpx(y: int) -> set[date]:
    """National holidays (with the substitute and sandwiched-day rules) plus Dec 31 - Jan 3."""
    hol = {date(y, 1, 1), nth_weekday(y, 1, 0, 2), date(y, 2, 11),
           date(y, 3, _equinox(y, 20.8431)), date(y, 4, 29), date(y, 5, 3), date(y, 5, 4),
           date(y, 5, 5), nth_weekday(y, 9, 0, 3), date(y, 9, _equinox(y, 23.2488)),
           date(y, 11, 3), date(y, 11, 23)}
    if y <= 2018:
        hol.add(date(y, 12, 23))
    elif y >= 2020:
        hol.add(date(y, 2, 23))
    marine = {2020: date(2020, 7, 23), 2021: date(2021, 7, 22)}
    sports = {2020: date(2020, 7, 24), 2021: date(2021, 7, 23)}
    mountain = {2020: date(2020, 8, 10), 2021: date(2021, 8, 8)}
    hol.add(marine.get(y, nth_weekday(y, 7, 0, 3)))
    hol.add(sports.get(y, nth_weekday(y, 10, 0, 2)))
    if y >= 2016:
        hol.add(mountain.get(y, date(y, 8, 11)))
    for d in sorted(hol):                    # substitute holiday: Sunday -> next free weekday
        if d.weekday() == 6:
            s = d + timedelta(days=1)
            while s in hol:
                s += timedelta(days=1)
            hol.add(s)
    for d in sorted(hol):                    # a weekday sandwiched between two holidays
        mid = d + timedelta(days=1)
        if mid not in hol and d + timedelta(days=2) in hol and mid.weekday() < 6:
            hol.add(mid)
    return hol | {date(y, 1, 2), date(y, 1, 3), date(y, 12, 31)}


VENUES = {"nyse": ("America/New_York", nyse, "MLK, Presidents, Good Friday, Memorial, Juneteenth "
                   "(2022+), Independence, Labor, Thanksgiving, Christmas, New Year; Sat->Fri, "
                   "Sun->Mon; a Saturday New Year is not observed"),
          "lse": ("Europe/London", lse, "New Year, Good Friday, Easter Monday, early May, "
                  "spring and summer bank holidays, Christmas, Boxing Day, with substitutions"),
          "xetra": ("Europe/Berlin", xetra, "New Year, Good Friday, Easter Monday, Labour Day, "
                    "Christmas Eve, Christmas, Boxing Day, New Year's Eve"),
          "jpx": ("Asia/Tokyo", jpx, "Japanese national holidays (equinoxes by formula, "
                  "substitute and sandwiched days), Dec 31 - Jan 3")}


def calendar(venue: str) -> dict:
    tz, rule, rules = VENUES[venue]
    days: set[date] = set()
    for y in YEARS:
        days |= rule(y)
    days |= {date.fromisoformat(d) for d in SPECIALS[venue]}
    days = {d for d in days if d.weekday() < 5}
    return {"name": f"holidays_{venue}", "tz": tz,
            "note": ("Exchange closure dates generated by rule in "
                     "desks/mt5/research/exchange_holidays.py; read by "
                     "mt5desk.family_tier1_ideas.holiday_drift. Weekend dates are dropped."),
            "rules": rules, "specials": SPECIALS[venue],
            "years": [YEARS.start, YEARS.stop - 1],
            "holidays": sorted(d.isoformat() for d in days)}


def write(out: Path = OUT, check: bool = False) -> list[str]:
    """Write (or with `check`, compare) every venue's file; returns the venues that differ."""
    differs = []
    for v in VENUES:
        path = out / f"holidays_{v}.json"
        text = json.dumps(calendar(v), indent=1) + "\n"
        try:
            same = path.read_text("utf-8") == text
        except OSError:
            same = False
        if not same:
            differs.append(v)
            if not check:
                out.mkdir(parents=True, exist_ok=True)
                path.write_text(text, "utf-8")
    return differs
